/* eslint-disable */
/**
 * Sarabun, subset and base64-encoded for embedding in the bill PDF.
 *
 * WHY THIS FILE EXISTS
 * jsPDF's built-in fonts (helvetica, times, courier) are Latin-1 only. Passing
 * Thai to them does not fail — it writes the raw UTF-16 code units into a
 * WinAnsi-encoded font, and the reader renders mojibake. Since a project name
 * in this console is normally Thai, the bill was unreadable exactly where it
 * mattered. An embedded font is the only fix; jsPDF cannot substitute one.
 *
 * WHY IT IS A .ts FILE OF BASE64 rather than a .ttf asset
 * jsPDF's VFS takes base64 strings, and a bundled binary asset would have to be
 * fetched and encoded at runtime. This module is imported with a dynamic
 * `import()` (see ProjectPanel.downloadBill) so its ~115 KB stays out of the
 * main chunk and is only fetched when somebody downloads a bill.
 *
 * FONT
 *   Sarabun — Copyright 2018 The Sarabun Project Authors
 *   https://github.com/cadsondemak/Sarabun
 *   SIL Open Font License 1.1 — http://scripts.sil.org/OFL
 *   The OFL permits embedding; it requires the copyright notice above to
 *   travel with the font, which is what this comment is for.
 *
 * REGENERATING (needed only to change the character coverage)
 *   curl -o Sarabun-Regular.ttf <google fonts ttf url>
 *   curl -o Sarabun-Bold.ttf    <google fonts ttf url>
 *   python3 -m fontTools.subset Sarabun-Regular.ttf \
 *     --unicodes="U+0020-007E,U+00A0-00FF,U+0E00-0E7F,U+2013,U+2014,U+2018,\
 *     U+2019,U+201C,U+201D,U+2022,U+2026,U+2192,U+00B7" \
 *     --layout-features="*" --no-hinting --desubroutinize \
 *     --output-file=Sub-Regular.ttf
 *   …then base64 each file into the constants below.
 *
 * COVERAGE: Basic Latin, Latin-1, the whole Thai block, and the punctuation
 * the bill actually prints (– — ' ' " " • … → ·). A character outside that set
 * renders as a blank box, so widen the subset rather than adding a second font.
 */

export const SARABUN_REGULAR_BASE64 =
  '';

export const SARABUN_BOLD_BASE64 =
  '';
